#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill: sets up the agent harness's runners
# (docs/plans/agent-harness.md, "Human prerequisites"). Run it from the repo
# root: bash .harness/setup-wizard.sh
# To set up only the harness supervisor routine (after the rest is done):
#   bash .harness/setup-wizard.sh harness-supervisor
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8
# The repository comes from GitHub (the origin remote), the names from the
# project's harness.config.json (.harness/src/config.ts).
REPO=$(gh repo view --json nameWithOwner --jq .nameWithOwner)
ORG=${REPO%%/*}
REPO_NAME=${REPO#*/}
config() { node .harness/src/cli/config.ts "$1"; }
BOT=$(config bot)
CODING_ENV=$(config environments.coding)
SUPERVISOR_ENV=$(config environments.supervisor)
CODING_ROUTINE=$(config routines.coding)
SUPERVISOR_ROUTINE=$(config routines.supervisor)

copy() {
  # Copies stdin to the clipboard where possible, so long values can be pasted.
  if command -v pbcopy >/dev/null 2>&1; then pbcopy && note "copied to your clipboard"
  elif command -v xclip >/dev/null 2>&1; then xclip -selection clipboard && note "copied to your clipboard"
  else cat >/dev/null; warn "couldn't copy to the clipboard, so copy it from the file shown"; fi
}

harness_supervisor() {
  stage "Harness supervisor: environment"
  say "The harness supervisor runs in its own cloud environment (docs/agents/cloud-routines.md)."
  open_url "https://claude.ai/code"
  step "Add an environment named $SUPERVISOR_ENV, set up like $CODING_ENV."
  pause "Press Enter once the environment exists"

  stage "Routine: harness-supervisor"
  say "Create the harness-supervisor routine, named $SUPERVISOR_ROUTINE, as docs/agents/cloud-routines.md describes (model, prompt, hourly trigger)."
  open_url "https://claude.ai/code/routines"
  step "New routine → fill it in → add an API trigger and an hourly trigger → Create."
  warn "Pick the $SUPERVISOR_ENV environment, and name its sessions Harness supervisor."
  step "Edit it → API trigger → copy the URL, then Generate token and copy it (it's shown once)."
  ask ROUTINE_URL "Paste the harness-supervisor URL:"
  ask_secret ROUTINE_TOKEN "Paste the harness-supervisor token:"
  set_secret ROUTINE_HARNESS_SUPERVISOR_URL "$ROUTINE_URL"
  set_secret ROUTINE_HARNESS_SUPERVISOR_TOKEN "$ROUTINE_TOKEN"
  # Its escalation label, for runs of just this part (the Labels stage has it too).
  gh label create needs-human --repo "$REPO" --color d93f0b --description "Escalated: waiting on the human" --force >/dev/null \
    || SKIPPED+=("label needs-human")
}

if [[ "${1:-}" == harness-supervisor ]]; then
  TOTAL_STAGES=2
  banner "Harness supervisor setup for $REPO"
  harness_supervisor
  finish
  return
fi

banner "Agent harness setup for $REPO"

stage "GitHub App: create it"
say "Agents act as their own GitHub App, so you can review and approve their PRs."
open_url "https://github.com/organizations/$ORG/settings/apps/new"
step "GitHub App name: $BOT (the bot in harness.config.json: change it there if the name is taken). Homepage URL: https://github.com/$REPO"
step "Webhook: untick Active."
step "Repository permissions: Contents, Issues, Pull requests, Variables and Workflows: Read and write; Checks: Read-only."
step "Where can this GitHub App be installed: Only on this account. Then Create GitHub App."
ask AGENT_APP_ID "Paste the App ID (shown under About):"
step "Under Private keys, click Generate a private key. A .pem file downloads."
# An unreadable path would otherwise store an empty secret, and every Actions
# run would fail minting its token ("privateKey option is required").
while true; do
  ask AGENT_APP_KEY_PATH "Path to the downloaded .pem file:"
  AGENT_APP_KEY_PATH="${AGENT_APP_KEY_PATH/#\~/$HOME}"
  if [[ -r "$AGENT_APP_KEY_PATH" ]] && grep -q "BEGIN .*PRIVATE KEY" "$AGENT_APP_KEY_PATH"; then break; fi
  warn "$AGENT_APP_KEY_PATH isn't a readable private key (.pem); try again"
done
set_var AGENT_APP_ID "$AGENT_APP_ID"
set_secret AGENT_APP_PRIVATE_KEY "$(cat "$AGENT_APP_KEY_PATH")"
note "Keep the .pem somewhere safe, or delete it: GitHub can generate a new one."

stage "GitHub App: install it"
step "On the App's page, click Install App, choose $ORG, then Only select repositories: $REPO_NAME."
pause "Press Enter once it's installed"

stage "Claude GitHub App"
say "Cloud sessions need the Claude GitHub App to clone and push."
open_url "https://github.com/apps/claude"
step "Install it on $ORG with access to $REPO_NAME."
open_url "https://claude.ai/code"
step "If claude.ai/code doesn't list $REPO yet, connect GitHub there."
pause "Press Enter once both are done"

stage "Cloud environment"
say "Create the $CODING_ENV environment exactly as the table in"
say "docs/agents/cloud-routines.md describes."
copy <.harness/cloud-setup.sh
note "The setup script is .harness/cloud-setup.sh: paste it into the environment."
open_url "https://claude.ai/code"
step "Open the environment selector, add an environment, and fill it in."
pause "Press Enter once the environment exists"

stage "Routine: agent-harness"
say "Create the agent-harness routine, named $CODING_ROUTINE, as docs/agents/cloud-routines.md describes (model, environment, prompt)."
open_url "https://claude.ai/code/routines"
step "New routine → fill it in → add an API trigger → Create."
warn "The form preselects the Default environment: pick $CODING_ENV."
step "Edit it → API trigger → copy the URL, then Generate token and copy it (it's shown once)."
ask ROUTINE_URL "Paste the agent-harness URL:"
ask_secret ROUTINE_TOKEN "Paste the agent-harness token:"
set_secret ROUTINE_AGENT_HARNESS_URL "$ROUTINE_URL"
set_secret ROUTINE_AGENT_HARNESS_TOKEN "$ROUTINE_TOKEN"

harness_supervisor

stage "Labels"
say "Creates (or updates) the labels in docs/agents/labels.md."
if confirm "Create the labels on $REPO now?"; then
  while IFS='|' read -r name color description; do
    if gh label create "$name" --repo "$REPO" --color "$color" --description "$description" --force >/dev/null; then
      printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$name"
    else
      SKIPPED+=("label $name")
    fi
  done <<'LABELS'
needs-triage|fbca04|A maintainer needs to evaluate this
needs-info|d4c5f9|Waiting on the reporter
agent-ready|0e8a16|Has a brief; starts /implement
ready-for-human|1d76db|Needs a human to implement it
wontfix|ffffff|Will not be actioned
agent-blocked|b60205|An agent stopped; see its comment
needs-review|5319e7|Restarts /review-pr
harness|000000|Tag: work on the agent harness
needs-human|d93f0b|Escalated: waiting on the human
LABELS
else
  SKIPPED+=("labels (see docs/agents/labels.md)")
fi

finish
}

run_wizard "$@"; exit
